// We want to be able to easily figure out how much our dinner bill is going to be after we order our lunch. Make a program which allows a user to enter in a cost for an entree, the percentage of sales tax, and the percentage we plan to tip (note: tip is applied only on the cost of the entree, not on top of the tax). Then, print out the total cost of the meal using printToScreen()

// Solution

let entree = +prompt("Please enter in the cost of your entree.")

let taxes = +prompt("Please enter in the sales tax percentage for your area.")

let tip = +prompt("Please enter in how much you plan to tip in percent for your meal.")

let total = 0;

let taxCost = entree * (taxes/100)

total += taxCost + entree;

let tipCost = entree * (tip/100)

total += tipCost;

printToScreen("The total cost of the meal is $" + total)

// DO NOT ALTER CODE WRITTEN BELOW THIS LINE

function printToScreen(text) {
  let r = Math.floor((Math.random() * 155));
  let g = Math.floor((Math.random() * 155));
  let b = Math.floor((Math.random() * 155));
  const svg = d3.select("body")
    .append("svg")
    .attr("width", 1500)
    .attr("height", 75);

  svg.append("text")
    .attr("y", 37.5)
    .attr("width", 450)
    .attr("height", 75)
    .attr("x", -1000)
    .attr("font-weight", "bold")
    .attr("font-size", "24px")
    .attr("fill", `rgb(${r},${g},${b}`)
    .attr("font-family", "Times New Roman")
    .text(text)
    .transition()
    .duration(1000)
    .attr("x", 37.5);
}

