function printToScreen(text) {

  let stringLimit = 50;
  let listOfStrings = [];

  while (text.length > stringLimit){
    let builtString = "";

    for(var i = 0; i < stringLimit; i++){
      builtString += text.slice(0,1);
      text = text.slice(1, text.length)
    }

    let currentChar = text[0];
    while (currentChar != " " && text.length > 1){
      builtString += text.slice(0,1);
      text = text.slice(1, text.length)
      currentChar = text[0];
    }
    builtString += text.slice(0,1);
    text = text.slice(1, text.length)
    listOfStrings.push(builtString);
  }
  if(text.length > 0){
    listOfStrings.push(text);
  }

  console.log(listOfStrings);
  for (let i = 0; i < listOfStrings.length; i ++){
    const svg = d3.select("body")
      .append("svg")
      .attr("width", 1500)
      .attr("height", 50);

    svg.append("text")
      .attr("y", 37.5)
      .attr("width", 450)
      .attr("height", 50)
      .attr("x", -1000)
      .attr("font-weight", "bold")
      .attr("font-size", "24px")
      .attr("fill", 255,255,255)
      .attr("font-family", "Times New Roman")
      .text(listOfStrings[i])
      .transition()
      .duration(1000)
      .attr("x", 37.5);
  }

}

