function printToScreen(startAngle, endAngle){
  let svg = d3
    .select("body")
    .append("svg")
    .attr("width", 800)
    .attr("height", 400)
    .append("g")
    .attr("transform", "translate(400,200)");
  let arc = d3
    .arc()
    .innerRadius(100)
    .outerRadius(150)
    .startAngle(startAngle)
    .endAngle(endAngle);

  let path = svg
    .attr("class", "arc");
  path
    .append("path")
    .attr("fill", "blue")
    .attr("d", arc);
}

